tinymce.PluginManager.add('upload', function(editor) {
    editor.ui.registry.addIcon('media-manager', '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" style="fill:rgba(0, 0, 0, 1);transform:;-ms-filter:"><path d="M18.944,11.112C18.507,7.67,15.56,5,12,5C9.244,5,6.85,6.611,5.757,9.15C3.609,9.792,2,11.82,2,14c0,2.757,2.243,5,5,5h3h1 h2h1h4c2.206,0,4-1.794,4-4C22,13.12,20.695,11.538,18.944,11.112z M13,14v3h-2v-3H8l4-5l4,5H13z"></path></svg>' );
    editor.ui.registry.addButton('upload', {
        tooltip: 'Media Manager',
        icon: 'media-manager',
        onAction: function () {
            $('#modal-file-manager').remove();
            $('#file_manager_input').val('tinymce');
            $.ajax({
                url: MEDIA_LOADER_URL,
                data: {action : 'tinymce'},
                dataType: 'html',
                success: function (html) {
                    $('body').append('<div class="modal fade file-manager" id="modal-file-manager" tabindex="-1" role="dialog" aria-hidden="true">' + html + '</div>');
                    $('#modal-file-manager').modal('show');
                }
            });
        }
    });

    return {
        getMetadata: function () {
            return  {
                name: 'Media Manager plugin',
                url: 'https://nhatky.date'
            };
        }
    };
});